def make_plot():
    plot__ = plt.subplots()

def add_circle(pos ,r):
    circle = plt.Circle((pos[0], pos[1]), r, color='brown', fill=True)
    plot__.add_patch(circle)

def plotpath(x_pos_list, y_pos_list):
    x = x_pos_list
    y = y_pos_list

    plot__.plot(
        x, y,
        label='object path',
        color=(78/255, 191/255, 217/255),
        linewidth=1,
        marker='o',
        markersize=2
    )

    # Mark the starting position
    plot__.scatter(
        x[0],
        y[0],
        color='green',
        s=80,
        zorder=5,
        label='starting position'
    )

    plot__.annotate(
        'START',
        (x[0], y[0]),
        xytext=(10, 10),
        textcoords='offset points'
    )

    plot__.set_xlabel('X-axis')
    plot__.set_ylabel('Y-axis')
    plot__.set_title('position tracker')

    plot__.grid(True, linestyle='--', alpha=0.6)
    plot__.legend()

def smallest(lst):

    lst1 = lst.sort()
    return lst[0]

def biggest(lst):

    lst1 = lst.sort()
    return lst[-1]

